from PIL import Image
import numpy as np, cv2
im=np.array(Image.open('first_frame.png').convert('RGB')).astype(float)
R,G,B=im.transpose(2,0,1)
m=((R>G*1.45+8)&(R>B*1.8+8)&(R>55)).astype(np.uint8)
# count red per row/col and detect empty interior
for y in range(30,144):
 xs=np.where(m[y])[0]
 if len(xs):
  # contiguous runs >=2
  runs=[];start=last=xs[0]
  for x in xs[1:]:
   if x>last+1:
    if last-start>=1:runs.append((start,last))
    start=x
   last=x
  if last-start>=1:runs.append((start,last))
  if y%2==0: print(y,runs)
PY"
